.print "========================================".print "AC-001: PK única no mart".print "========================================"SELECT 'FALHA' AS status, co_fat_cidadao_pec, COUNT(*) cntFROM mart_lista_nominal_hipertensaoGROUP BY co_fat_cidadao_pecHAVING COUNT(*) > 1;.print "========================================".print "AC-002: Nenhum falecido na lista".print "========================================"SELECT 'FALHA' AS status, c.co_fat_cidadao_pec, c.no_cidadaoFROM mart_lista_nominal_hipertensao mJOIN raw_cidadao_pec c ON m.co_fat_cidadao_pec = c.co_fat_cidadao_pecWHERE c.st_faleceu = '1';.print "========================================".print "AC-003: Status válido e não nulo".print "========================================"SELECT 'FALHA' AS status, co_fat_cidadao_pec, 'consulta' prática, consulta_statusFROM mart_lista_nominal_hipertensaoWHERE consulta_status NOT IN ('EM_DIA','ATRASADA','NUNCA_REALIZADA') OR consulta_status IS NULLUNION ALLSELECT 'FALHA', co_fat_cidadao_pec, 'pa', pa_statusFROM mart_lista_nominal_hipertensaoWHERE pa_status NOT IN ('EM_DIA','ATRASADA','NUNCA_REALIZADA') OR pa_status IS NULLUNION ALLSELECT 'FALHA', co_fat_cidadao_pec, 'peso_altura', peso_altura_statusFROM mart_lista_nominal_hipertensaoWHERE peso_altura_status NOT IN ('EM_DIA','ATRASADA','NUNCA_REALIZADA') OR peso_altura_status IS NULL;.print "========================================".print "AC-004: Soma dos status = total (por prática)".print "========================================"SELECT 'FALHA' AS status, 'consulta' prática,       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao) total,       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE consulta_status='EM_DIA') em_dia,       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE consulta_status='ATRASADA') atrasada,       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE consulta_status='NUNCA_REALIZADA') nunca,       em_dia + atrasada + nunca somaWHERE em_dia + atrasada + nunca <> totalUNION ALLSELECT 'FALHA', 'pa',       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao),       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE pa_status='EM_DIA'),       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE pa_status='ATRASADA'),       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE pa_status='NUNCA_REALIZADA'),       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE pa_status='EM_DIA')       + (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE pa_status='ATRASADA')       + (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE pa_status='NUNCA_REALIZADA')WHERE soma <> totalUNION ALLSELECT 'FALHA', 'peso_altura',       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao),       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE peso_altura_status='EM_DIA'),       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE peso_altura_status='ATRASADA'),       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE peso_altura_status='NUNCA_REALIZADA'),       (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE peso_altura_status='EM_DIA')       + (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE peso_altura_status='ATRASADA')       + (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao WHERE peso_altura_status='NUNCA_REALIZADA')WHERE soma <> total;.print "========================================".print "AC-005: Consulta nunca tem status NUNCA_REALIZADA".print "========================================"SELECT 'FALHA' AS status, co_fat_cidadao_pec, no_cidadaoFROM mart_lista_nominal_hipertensaoWHERE consulta_status = 'NUNCA_REALIZADA';.print "========================================".print "AC-006: Nenhuma data no futuro (> data_referencia)".print "========================================"SELECT 'FALHA' AS status, co_fat_cidadao_pec, 'consulta' prática, consulta_dt_ultima dtFROM mart_lista_nominal_hipertensaoWHERE consulta_dt_ultima > (SELECT data_referencia FROM param LIMIT 1)UNION ALLSELECT 'FALHA', co_fat_cidadao_pec, 'pa', pa_dt_ultimaFROM mart_lista_nominal_hipertensaoWHERE pa_dt_ultima > (SELECT data_referencia FROM param LIMIT 1)UNION ALLSELECT 'FALHA', co_fat_cidadao_pec, 'peso_altura', peso_altura_dt_ultimaFROM mart_lista_nominal_hipertensaoWHERE peso_altura_dt_ultima > (SELECT data_referencia FROM param LIMIT 1);.print "========================================".print "AC-007: Staging: PKs dedupadas (no duplicatas)".print "========================================"SELECT 'FALHA' AS status, 'atendimento' tabela, COUNT(*) total, COUNT(DISTINCT co_seq_fat_atd_ind) distintosFROM stg_atendimentoHAVING total <> distintosUNION ALLSELECT 'FALHA', 'procedimento', COUNT(*), COUNT(DISTINCT co_seq_fat_proced)FROM stg_procedimentosHAVING COUNT(*) <> COUNT(DISTINCT co_seq_fat_proced);.print "========================================".print "AC-008: Reativados estão na coorte".print "========================================"SELECT 'FALHA' AS status, 'reativado ausente da coorte'WHERE (SELECT COUNT(*) FROM mart_lista_nominal_hipertensao       WHERE co_fat_cidadao_pec IN (SELECT co_fat_cidadao_pec FROM reativados)) <> (SELECT COUNT(*) FROM reativados);.print "========================================".print "AC-009: CRÍTICA — Técnico em consulta sai ATRASADA".print "========================================"SELECT 'FALHA: ARMADILHA' AS status, m.co_fat_cidadao_pec, m.no_cidadao, m.consulta_statusFROM mart_lista_nominal_hipertensao mWHERE m.consulta_status = 'EM_DIA'  AND m.co_fat_cidadao_pec IN (    SELECT DISTINCT co_fat_cidadao_pec    FROM stg_atendimento    WHERE SUBSTR(nu_cbo, 1, 4) = '3222'      AND dt_registro >= '2026-02-01'      AND dt_registro <= (SELECT data_referencia FROM param LIMIT 1)  );.print "========================================".print "AC-010: Valores de PA quando não NUNCA_REALIZADA".print "========================================"SELECT 'FALHA' AS status, co_fat_cidadao_pec, pa_status, pa_sistolica, pa_diastolicaFROM mart_lista_nominal_hipertensaoWHERE pa_status <> 'NUNCA_REALIZADA' AND (pa_sistolica IS NULL OR pa_diastolica IS NULL);.print "========================================".print "AC-011: Nenhuma idade negativa".print "========================================"SELECT 'FALHA' AS status, co_fat_cidadao_pec, no_cidadao, dt_nascimento, idadeFROM mart_lista_nominal_hipertensaoWHERE idade < 0;.print "========================================".print "AC-012: Contagem mestre = 325".print "========================================"SELECT 'FALHA: Total incorreto' AS status, COUNT(*) totalFROM mart_lista_nominal_hipertensaoWHERE COUNT(*) <> 325;